  "e": "Een overlandvlucht is een vlucht **tussen twee punten op een afstand van 40 km of meer**.\n\n**Wat zegt het KB?**\nDe definitie is belangrijk tijdens je opleiding: voor de klassebevoegdverklaring heb je onder meer 5 uur overlandvluchten nodig, en solo overland mag je pas na twee overlandvluchten in dubbelbesturing en met schriftelijke toelating van je instructeur.\n\n**In de praktijk:**\nEen lokale vlucht is iets anders: die blijft rond een luchtvaartterrein, op een afstand waarop optische seinen vanaf de grond steeds waarneembaar zijn.",
