  "e": "Na het Belgische nationaliteitskenmerk **OO** volgt een registratiekenmerk van **drie cijfers of een combinatie van maximum drie letters en cijfers**, zoals bepaald door de minister of zijn gemachtigde.\n\n**Wat zegt het KB?**\nDe plaats, afmetingen en karakters van het kenmerk worden door de minister of zijn gemachtigde voorgeschreven.\n\n**In de praktijk:**\nAls gezagvoerder moet je erover waken dat het kenmerk goed zichtbaar is.",
