  "c": 0,
  "e": "De BTTL is **drie jaar** geldig.\n\n**Wat zegt het KB?**\nHet DGLV kan de geldigheid verlengen als de eigenaar verklaart dat het toestel in overeenstemming is gebleven met het toegelaten type en onderhouden wordt volgens het gebruikershandboek.\n\n**In de praktijk:**\nZonder geldige BTTL (of voorlopige toelating, de luchtvaartpas) mag een in België geregistreerd ULM niet vliegen. De BTTL hoort ook bij je boorddocumenten.\n\n**Valkuil:**\nTwee jaar is de maximale geldigheid van een toelating tot commerciële vluchtuitvoering.",
