  "c": 0,
  "e": "Een belangrijke wijziging moet **vooraf**, dus vóór de toepassing ervan, **door de minister of zijn gemachtigde worden goedgekeurd**.\n\n**Wat zegt het KB?**\nEen belangrijke wijziging raakt de typetoelating of heeft een aanzienlijk effect op prestaties, massa, zwaartepuntsgrenzen, structurele weerstand, betrouwbaarheid of gebruikskenmerken. Voor een individueel toestel kan de eigenaar de aanvraag indienen.\n\n**Valkuil:**\nEen belangrijke wijziging zonder voorafgaande toelating is een reden om de BTTL in te trekken of op te schorten.",
