  "basis": "SERA",
  "q": "Op een luchtvaartterrein in een CTR liggen de gemelde wolkenbasis en het grondzicht onder de VFR-minima voor een CTR. Je hebt geen klaring. Wat mag je als VFR-vlucht NIET doen?",
  "o": [
   "Het luchtvaartterreinverkeersgebied (ATZ) of het plaatselijk verkeerscircuit binnenvliegen",
   "Er alleen landen; het circuit binnenvliegen om de baan te bekijken mag wel",
   "Er alleen opstijgen; landen mag altijd",
   "Niets, de regel geldt alleen voor IFR-vluchten"
  ],
  "c": 0,
  "e": "Het ATZ of het verkeerscircuit binnenvliegen. Onder de minima geldt het verbod niet alleen voor opstijgen en landen, maar ook voor het binnenvliegen van het ATZ (aerodrome traffic zone) en het verkeerscircuit.\n\n**Wat zegt SERA?**\nZonder klaring van de luchtverkeersleiding mag een VFR-vlucht niet opstijgen, niet landen en het ATZ of circuit niet binnenvliegen als de gemelde weersomstandigheden onder 1 500 ft wolkenbasis of 5 km grondzicht liggen.\n\n**Valkuil:**\nEven het circuit in om te kijken mag niet. Je hebt eerst een klaring nodig, bv. een special VFR-klaring.",
  "src": "sera",
  "ref": "SERA.5005 – Zichtvliegvoorschriften (VFR)",
  "doc": "sera",
  "art": "SERA.5005",
  "citaat": "VFR flights shall not take off or land at an aerodrome within a control zone, or enter the aerodrome traffic zone or aerodrome traffic circuit, when the reported meteorological conditions at that aerodrome are below the following minima",
  "opgesteld": "AI (Claude), op basis van de wettekst",
