  "e": "Je moet voortdurend zicht op het aardoppervlak houden. 's Nachts geldt dat in alle klassen van B tot G, op of onder 3 000 ft AMSL of 1 000 ft boven het terrein (als dat hoger is).\n\n**Wat zegt SERA?**\nBij VFR bij nacht moet de piloot in luchtruimklassen B, C, D, E, F en G in die onderste band ononderbroken zicht op het aardoppervlak behouden.\n\n**Valkuil:**\nOverdag is zicht op de grond alleen vereist in klasse F en G laag. 's Nachts geldt het ook in gecontroleerd luchtruim zoals klasse D.\n\n**In de praktijk:**\nBoven een donker gebied zonder lichten kun je de grond 's nachts gemakkelijk uit het oog verliezen. Plan je route daarop.",
