  "c": 0,
  "e": "Klasse B. Daar krijgen alle vluchten luchtverkeersleidingsdienst en worden ze allemaal van elkaar gesepareerd, ook VFR van VFR.\n\n**Wat zegt SERA?**\nKlasse B: IFR en VFR toegestaan, luchtverkeersleidingsdienst voor iedereen, alle vluchten gesepareerd, permanente radioverbinding en klaring verplicht.\n\n**Valkuil:**\nIn klasse C wordt VFR alleen van IFR gesepareerd. VFR onderling krijgt daar alleen verkeersinformatie.\n\n**Goed om te weten:**\nIn klasse A worden ook alle vluchten gesepareerd, maar daar is VFR niet toegelaten.",
  "src": "sera",
  "ref": "SERA.6001 – Luchtruimclassificatie",
  "doc": "sera",
  "art": "SERA.6001",
