  "loText": "Het gebruik en de mogelijkheden van een seinlamp uitleggen, en de betekenis van de lichtseinen van de toren noemen …",
  "basis": "SERA",
  "q": "Je taxiet op een gecontroleerd luchtvaartterrein zonder werkende radio. De toren richt een ononderbroken rood licht op je. Wat betekent dit?",
  "o": [
   "Stop",
   "Taxi weg van de baan in gebruik",
   "Keer terug naar de plaats van vertrek op het luchtvaartterrein",
   "Wacht met opstijgen, maar blijf verder taxiën naar het baanbegin"
  ],
  "c": 0,
  "e": "Een ononderbroken rood licht naar een luchtvaartuig op de grond betekent: stop.\n\n**Wat zegt SERA?**\nIn de tabel met lichtseinen staat voor ononderbroken rood in de vlucht 'wijk uit en blijf cirkelen', en op de grond eenvoudig 'stop'.\n\n**In de praktijk:**\nRem en blijf staan tot je een volgend sein krijgt, bijvoorbeeld een groen knipperlicht (geklaard om te taxiën).\n\n**Valkuil:**\nWeg taxiën van de baan in gebruik is de betekenis van een rood knipperlicht op de grond. Bij ononderbroken rood beweeg je niet verder.",
