  "loText": "Het gebruik en de mogelijkheden van een seinlamp uitleggen, en de betekenis van de lichtseinen van de toren noemen …",
  "basis": "SERA",
  "q": "Je staat op het platform van een gecontroleerd luchtvaartterrein en je radio werkt niet. De toren richt een groen knipperlicht op je. Wat betekent dit?",
  "o": [
   "Geklaard om te taxiën",
   "Geklaard om op te stijgen",
   "Stop",
   "Keer terug naar de plaats op het luchtvaartterrein van waar je vertrokken bent"
  ],
  "c": 0,
  "e": "Een groen knipperlicht naar een luchtvaartuig op de grond betekent: geklaard om te taxiën.\n\n**Wat zegt SERA?**\nIn de vlucht betekent hetzelfde groene knipperlicht 'keer terug om te landen'; de eigenlijke landingsklaring volgt later met ononderbroken groen.\n\n**In de praktijk:**\nTaxi met de nodige voorzichtigheid en houd de toren in het oog: aan de wachtpositie wacht je op een ononderbroken groen licht voor de start.\n\n**Valkuil:**\nOnonderbroken groen op de grond is de startklaring. Een knipperend groen licht geeft je alleen toestemming om te taxiën, niet om te vertrekken.",
  "src": "sera",
  "ref": "SERA Aanhangsel 1 – Signalen (oorspronkelijke tekst 2012)",
