  "basis": "SERA",
  "q": "Je taxiet op een gecontroleerd luchtvaartterrein zonder radiocontact. De toren richt een wit knipperlicht op je. Wat moet je doen?",
  "o": [
   "Terugkeren naar de plaats op het luchtvaartterrein van waar je vertrokken bent",
   "Wegtaxiën van de baan in gebruik",
   "Stoppen en wachten op verdere seinen",
   "Doortaxiën naar de wachtpositie en daar wachten op de startklaring"
  ],
  "c": 0,
  "e": "Een wit knipperlicht naar een luchtvaartuig op de grond betekent: keer terug naar de plaats op het luchtvaartterrein van waar je vertrokken bent.\n\n**Wat zegt SERA?**\nIn de vlucht betekent een wit knipperlicht 'land hier en ga naar het platform'. Op de grond stuurt het je terug naar je vertrekpunt.\n\n**In de praktijk:**\nDit sein kan je bijvoorbeeld krijgen als je vertrek niet kan doorgaan. Taxi voorzichtig terug en zoek contact met de toren, bv. via telefoon.\n\n**Valkuil:**\nWegtaxiën van de baan in gebruik is de betekenis van een rood knipperlicht op de grond, niet van een wit knipperlicht.",
