  "loText": "Het gebruik en de mogelijkheden van een seinlamp uitleggen, en de betekenis van de lichtseinen van de toren noemen …",
  "basis": "SERA",
  "q": "Je hebt van de toren al een ononderbroken groen licht gekregen en zit in de eindnadering. Plots wordt vanaf de toren een rode vuurpijl afgeschoten. Wat betekent dit?",
  "o": [
   "Ondanks eerdere aanwijzingen voorlopig niet landen",
   "De landingsklaring blijft geldig, maar let op ander verkeer",
   "Een luchtvaartuig in de buurt is in nood; land zo snel mogelijk om de baan vrij te maken",
   "Land en verlaat de baan zo snel mogelijk"
  ],
  "c": 0,
  "e": "Een rode lichtkogel of vuurpijl vanaf de toren betekent: ondanks eerdere aanwijzingen voorlopig niet landen.\n\n**Wat zegt SERA?**\nDit sein vervangt een eerder gegeven landingsklaring. Ook al kreeg je al groen licht, je mag nu niet landen.\n\n**In de praktijk:**\nVoer een doorstart uit, houd uitkijk en wacht op een nieuw sein, zoals ononderbroken groen.\n\n**Valkuil:**\nRode vuurpijlen die een luchtvaartuig zelf één voor één afschiet zijn een noodsignaal. Komt de rode vuurpijl van de toren, dan is het een (tijdelijk) landingsverbod.",
  "src": "sera",
  "ref": "SERA Aanhangsel 1 – Signalen (oorspronkelijke tekst 2012)",
  "doc": "sera2012",
  "art": "Aanhangsel 1",
  "citaat": "Rode lichtkogels of vuurpijlen Ondanks eerdere aanwijzingen voorlopig niet landen",
