  "c": 0,
  "e": "Je trekt je landingsgestel in (indien mogelijk) en laat je landingslichten knipperen terwijl je over de baan in gebruik vliegt op een hoogte tussen 300 m (1 000 ft) en 600 m (2 000 ft) boven het luchtvaartterrein, en je blijft boven de baan cirkelen.\n\n**Wat zegt SERA?**\nDit sein betekent 'het aangewezen luchtvaartterrein is ongeschikt'. Kan je de landingslichten niet laten knipperen, gebruik dan andere beschikbare lichten. De onderschepper antwoordt met 'volg mij' naar een ander terrein of met 'u mag doorgaan'.\n\n**Valkuil:**\nOnregelmatig knipperen van alle lichten betekent 'in nood'. Regelmatig aan en uit schakelen van alle lichten betekent 'kan niet uitvoeren'.",
